 static readonly string[] Exterior={"SurveillanceRadar","DefenseTurret","PatrolDepot","ExpeditionBeacon","RescueHangar","ExportDock"};
 static readonly string[] Photos={"SurveillanceRadar","DefenseTurret","PatrolDepot","LogisticsHub","FreightWarehouse","ExpeditionCenter","ExpeditionBeacon","EmergencyHospital","RescueHangar","EmergencyShelter","PrivateResidence","Academy","CommunityCafe","TradeTerminal","ExportDock","SecurityCommand","EmergencyHospital-inside","PrivateResidence-inside","Academy-inside","LogisticsHub-inside","CommunityCafe-inside","interface-0","interface-1","interface-2","interface-3","interface-4","interface-5"};
 void Awake(){self=this;Application.runInBackground=true;output=Environment.GetCommandLineArgs().First(x=>x.StartsWith("-community-out=")).Substring(15);Directory.CreateDirectory(output);new Harmony("local.planetbase.community.qa").PatchAll(typeof(CommunityProbe).Assembly);}
 [HarmonyPatch(typeof(ServerInterfaceSteam),nameof(ServerInterfaceSteam.isAvailable))]
 static class Offline{static bool Prefix(ref bool __result){__result=false;return false;}}
 [HarmonyPatch(typeof(GameManager),nameof(GameManager.update))]
 static class Drive
 {
  static void Postfix(GameManager __instance,ref GameManager.State ___mState){try{
   if(step==6){Studio.Update();return;}
   if(step==0&&__instance.getGameState() is GameStateTitle&&___mState==GameManager.State.Updating){Check(Util.getFilesFolder().Contains("PlanetbaseResourceMenu-qa"),"isolated QA profile");step=1;__instance.setGameStateGameLoad(Path.Combine(SaveData.FolderName,"save1.sav"),0,null);return;}
   if(!(__instance.getGameState() is GameStateGame game)||___mState!=GameManager.State.Waiting)return;
   game.onStartUpdating();___mState=GameManager.State.Updating;Singleton<TimeManager>.getInstance().pause();
   if(step==1){step=2;Build();Exercise();PrepareSave(game);}
   else if(step==3){step=4;Reload();captureAt=Time.realtimeSinceStartup+1;}
  }catch(Exception e){Fail(e);}}
 }
 static void Build()
 {
  Check(Singleton<ServerInterfaceManager>.getInstance().getInterfaceName().Contains("Offline"),"offline achievements");
  Check(TypeList<ResourceType,ResourceTypeList>.find<NuclearFuelRod>().getTypeIndex()==14,"original nuclear fuel index preserved");
  Check(TypeList<ResourceType,ResourceTypeList>.find<FieldSample>().getTypeIndex()==22,"community resources appended after solar resources");
  Check(SpecializationList.getBotSpecializations().Count==9,"all nine bot specializations registered in native bot list");
  var terrain=Singleton<TerrainGenerator>.getInstance();terrain.flatten(new Vector3(1260,0,1140),170,terrain.getFloorHeight());terrain.clearArea(new Vector3(1260,0,1140),170);Physics.SyncTransforms();RegenerateExterior();
  Module previous=Module.findOfType(TypeList<ModuleType,ModuleTypeList>.find<ModuleTypeCanteen>());
  for(int i=0;i<Interior.Length;i++){
   int x=i<5?i:9-i;float z=i<5?1123.5f:1150.5f;var m=Make(Interior[i],new Vector3(1185+x*23,0,z));Link(previous,m);previous=m;rooms[Interior[i]]=m;
  }
  for(int i=0;i<Exterior.Length;i++){
   var p=Exterior[i]=="ExportDock"?new Vector3(1317,0,1176):new Vector3(1300+(i%3)*23,0,i<3?1123.5f:1150.5f);var m=Make(Exterior[i],p);var from=i%3==0?World.Modules.Where(x=>x!=m&&x.isBuilt()&&x.getLocation()==Location.Interior).OrderBy(x=>(x.getPosition()-m.getPosition()).sqrMagnitude).First():rooms[Exterior[i-1]];Link(from,m);rooms[Exterior[i]]=m;
  }
  var destination=Module.create(new Vector3(1231,0,1097),1,TypeList<ModuleType,ModuleTypeList>.find<ModuleTypeStorage>());Finish(destination);Link(rooms["FreightWarehouse"],destination);rooms["Destination"]=destination;
  new Grid().calculate(rooms["SecurityCommand"]);foreach(var m in World.Modules)Supply(m);
  Equip<SecurityDispatch>("SecurityCommand");Equip<LogisticsConsole>("LogisticsHub");Equip<VehicleFabricator>("LogisticsHub");Equip<SupplyPacker>("LogisticsHub");Equip<SampleAnalyzer>("ExpeditionCenter");Equip<TraumaBed>("EmergencyHospital");Equip<MedicalCabinet>("EmergencyHospital");Equip<PrivateBunk>("PrivateResidence");Equip<TrainingConsole>("Academy");Equip<CafeSeat>("CommunityCafe");Equip<TradeConsole>("TradeTerminal");
  Singleton<TechManager>.getInstance().acquire(TypeList<Tech,TechList>.find<TechSolarRobotics>());
  Check(Interior.All(n=>HelpManager.getInstance().findItem(n)!=null)&&Exterior.All(n=>HelpManager.getInstance().findItem(n)!=null),"all sixteen buildings have native help");
  foreach(var p in equipment.Where(p=>Catalog.IsEquipment(p.Key))){var root=p.Value.getGameObject();Check(root.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="Community equipment body"),"own equipment model "+p.Key);Check(p.Value.getAnchorPoint()!=null,"native interaction marker "+p.Key);}
  CommunityState.Current.Enabled[3]=false;NavigationGraph.requestUpdateCache();NavigationGraph.update();
  self.Logger.LogInfo("COMMUNITY QA fixture built: sixteen modules, warehouse, eleven furnishings.");
 }
 static void Exercise()
 {
  var engineer=World.Characters.First(c=>c is Colonist&&c.getSpecialization() is Engineer);var fabricator=equipment["VehicleFabricator"];
  for(int i=0;i<3;i++){fabricator.setProducedItemIndex(i);StockMachine(fabricator,"MachineParts","VehicleChassis","Semiconductors");Produce(engineer,fabricator);Check(fabricator.getResourceContainer().getResourceCount()==0,"vehicle recipe consumes all three inputs "+i);}
  var hauler=World.Characters.Single(c=>c.getSpecialization() is FreightHauler);var rescuer=World.Characters.Single(c=>c.getSpecialization() is RescueRover);var explorer=World.Characters.Single(c=>c.getSpecialization() is ExpeditionRover);haulerId=hauler.getId();rescuerId=rescuer.getId();explorerId=explorer.getId();
  Check(hauler.getSelectionModel().GetComponentsInChildren<Transform>(true).Any(t=>t.name=="Community vehicle equipment"),"manufactured hauler uses own model");
  StockMachine(equipment["SupplyPacker"],"Metal","Bioplastic");Produce(engineer,equipment["SupplyPacker"]);Check(equipment["SupplyPacker"].getResourceContainer().getCountOf(TypeList<ResourceType,ResourceTypeList>.find<SupplyCrate>())==1,"native supply packing recipe");
  StockMachine(equipment["SampleAnalyzer"],"FieldSample");Produce(engineer,equipment["SampleAnalyzer"]);Check(equipment["SampleAnalyzer"].getResourceContainer().getCountOf(TypeList<ResourceType,ResourceTypeList>.find<ResearchPacket>())==1,"native sample analysis produces research report");
  Store(engineer,rooms["FreightWarehouse"],"Metal",6);Prep(hauler,Location.Interior,rooms["FreightWarehouse"].getFloorPosition());var s=CommunityState.Current;s.Source=rooms["FreightWarehouse"].getId();s.Destination=rooms["Destination"].getId();s.ResourceIndex=Array.FindIndex(Orders.HaulTypes(),r=>r is Metal);
  self.Logger.LogInfo("FREIGHT start: "+Orders.Route(hauler));Check(s.Orders.ContainsKey(haulerId),"freight route assigned");Orders.Tick(.1f);Check(s.Orders[haulerId].Cargo.Count==3,"hauler loads three real crates");Check(s.Orders[haulerId].Cargo.All(id=>World.Cargo(id)?.getState()==Resource.State.Loaded),"all freight resources held in native Loaded state");
  Vector3 start=hauler.getPosition();int before=Stored(rooms["Destination"],"Metal");for(int i=0;i<2500&&Stored(rooms["Destination"],"Metal")<before+3;i++){hauler.update(.1f);Orders.Tick(.1f);}Check((hauler.getPosition()-start).sqrMagnitude>25,"freight carrier travels native navigation");Check(Stored(rooms["Destination"],"Metal")>=before+3,"three crates delivered to actual destination storage slots");Orders.Cancel(haulerId);
  Store(engineer,rooms["FreightWarehouse"],"Spares",2);var turret=rooms["DefenseTurret"];var target=Character.create(SpecializationList.IntruderInstance,turret.getPosition()+Vector3.right*12,Location.Exterior);float health=Value(target,CharacterIndicator.Health);Defense.Tick(.1f);Check(CommunityState.Current.Detected.Contains(target.getId()),"powered radar detects physical intruder");Check(Value(target,CharacterIndicator.Health)<health,"powered turret damages exterior intruder");Check(s.Machine(turret.getId()).Charges==19,"one spare gives twenty shots and first shot consumes one charge");
  float after=Value(target,CharacterIndicator.Health);turret.setPower(false);Defense.Tick(5);Check(Value(target,CharacterIndicator.Health)==after,"turret stops firing on power loss");Supply(turret);target.destroy();
  var guard=Character.create(TypeList<Specialization,SpecializationList>.find<Guard>(),rooms["PatrolDepot"].getPosition()+new Vector3(-6,0,-13),Location.Exterior);guardId=guard.getId();Check(Defense.AssignPatrol(guard).Contains("asignada"),"guard assigned to powered patrol depot");var patrolStart=guard.getPosition();for(int i=0;i<300&&(guard.getPosition()-patrolStart).sqrMagnitude<4;i++){guard.update(.1f);Orders.Tick(.1f);}Check((guard.getPosition()-patrolStart).sqrMagnitude>=4,"patrol physically advances through native navigation");Orders.Cancel(guardId);
  string map=Exploration.Map();self.Logger.LogInfo("EXPLORATION map: "+map);Check(s.Sites.Count>0&&s.SitesMapped,"reachable expedition signals generated");int siteCount=s.Sites.Count;Exploration.Map();Check(s.Sites.Count==siteCount,"mapping twice does not duplicate signals");var site=s.Sites[0];Prep(explorer,Location.Exterior,site.Position+Vector3.right*7);Check(Exploration.Send(explorer,site.Id).Contains("asignada"),"expedition assigned to unit");Vector3 exStart=explorer.getPosition();for(int i=0;i<1000&&s.Orders.TryGetValue(explorerId,out var order)&&order.Phase==0;i++){explorer.update(.1f);Orders.Tick(.1f);}Check(site.Done,"signal explored after physical approach and ten seconds work");Check((explorer.getPosition()-exStart).sqrMagnitude>1,"expedition unit moves before recovery");Check(s.Orders[explorerId].Cargo.Count==3,"expedition physically loads three rewards");Orders.Cancel(explorerId);
  var cafe=equipment["CafeSeat"];Prep(engineer,Location.Interior,cafe.getAnchorPoint().position);Set(engineer,CharacterIndicator.Morale,.1f);var visit=Interaction.create<InteractionComponentRestore>(engineer,cafe);visit.update(20);Check(Value(engineer,CharacterIndicator.Morale)>.1f,"cafe seat restores morale through native interaction");visit.destroy();
  var bunk=equipment["PrivateBunk"];Check(bunk.getComponentType().getStatusRecoveryTime(CharacterIndicator.Sleep)==180,"private bunk native sleep recovery configured");
  GiveCoins(1000);Store(engineer,rooms["FreightWarehouse"],"SupplyCrate",4);int coins=Resource.getCountOfType(ResourceTypeList.CoinsInstance);Check(Commerce.Accept(0).Contains("aceptado"),"trade contract accepted");Check(Resource.getCountOfType(ResourceTypeList.CoinsInstance)==coins-30,"contract deposit charged once");Commerce.Accept(1);Check(Resource.getCountOfType(ResourceTypeList.CoinsInstance)==coins-30,"second acceptance cannot charge another deposit");int crates=Resource.getCountOfType(TypeList<ResourceType,ResourceTypeList>.find<SupplyCrate>());Check(Commerce.Export().Contains("entregada"),"available network cargo exported");Check(Resource.getCountOfType(TypeList<ResourceType,ResourceTypeList>.find<SupplyCrate>())==crates-4,"contract consumes exactly four physical crates");Commerce.Tick(45);Check(s.Contract==-1&&s.ContractsDone==1,"contract shipment settles");Check(Resource.getCountOfType(ResourceTypeList.CoinsInstance)==coins+220,"one reward and deposit returned");Commerce.Tick(45);Check(Resource.getCountOfType(ResourceTypeList.CoinsInstance)==coins+220,"settled contract does not pay twice");
  s.TradeCooldown=0;Check(Commerce.Import(1).Contains("pagada"),"medical import accepted");int meds=Resource.getCountOfType(ResourceTypeList.MedicalSuppliesInstance);rooms["ExportDock"].setPower(false);Commerce.Tick(60);Check(s.Import>=0&&Resource.getCountOfType(ResourceTypeList.MedicalSuppliesInstance)==meds,"import pauses while dock has no power");Supply(rooms["ExportDock"]);Commerce.Tick(60);Check(s.Import==-1&&Resource.getCountOfType(ResourceTypeList.MedicalSuppliesInstance)==meds+3,"import delivers three physical medical supplies");Commerce.Tick(60);Check(Resource.getCountOfType(ResourceTypeList.MedicalSuppliesInstance)==meds+3,"import cannot duplicate delivery");
  var trainee=World.Characters.First(c=>c is Colonist&&c!=engineer&&!(c.getSpecialization() is Medic));traineeId=trainee.getId();var desk=equipment["TrainingConsole"];Prep(trainee,Location.Interior,desk.getAnchorPoint().position);Store(engineer,rooms["FreightWarehouse"],"ResearchPacket",4);string next=trainee.getSpecialization() is Engineer?"Worker":"Engineer";
  Check(Orders.Train(trainee,next).Contains("iniciada"),"paid retraining starts");Orders.Tick(.1f);Orders.Tick(120);trainingAtSave=s.Orders[traineeId].Work;Check(trainingAtSave>=120&&trainingAtSave<300,"training advances while actually using study desk");rooms["Academy"].setPower(false);Orders.Tick(30);Check(s.Orders[traineeId].Work==trainingAtSave,"power failure pauses study progress");Supply(rooms["Academy"]);
  s.Enabled[3]=true;var patient=World.Characters.First(c=>c is Colonist&&c!=engineer&&c.getId()!=traineeId&&!(c.getSpecialization() is Guard));patientId=patient.getId();Prep(patient,Location.Exterior,rooms["RescueHangar"].getPosition()+new Vector3(0,0,16));Set(patient,CharacterIndicator.Health,.3f);Prep(rescuer,Location.Exterior,patient.getPosition()+Vector3.right*8);Vector3 rescueStart=rescuer.getPosition();
  for(int i=0;i<1000&&(!s.Orders.TryGetValue(rescuerId,out var rescue)||rescue.Phase==0);i++){rescuer.update(.1f);Orders.Tick(.1f);}Check(s.Orders.TryGetValue(rescuerId,out var active)&&active.Phase==1&&active.Target==patientId,"ambulance reaches and collects injured exterior colonist");Check((rescuer.getPosition()-rescueStart).sqrMagnitude>1,"ambulance moves to patient through navigation");Check(Orders.Passenger(patient)!=null,"patient ownership recorded for transport");
  self.Logger.LogInfo("COMMUNITY QA six feature groups exercised; preparing active tasks for reload.");
 }
 static void PrepareSave(GameStateGame game)
 {
  var s=CommunityState.Current;var engineer=World.Characters.First(c=>c is Colonist&&c.getSpecialization() is Engineer&&c.getId()!=traineeId);var hauler=World.Unit(haulerId);Store(engineer,rooms["FreightWarehouse"],"Metal",3);Prep(hauler,Location.Interior,rooms["FreightWarehouse"].getFloorPosition());Orders.Route(hauler);Orders.Tick(.1f);freightIds=s.Orders[haulerId].Cargo.ToArray();Check(freightIds.Length==3,"three active freight cargo ids before save");
  var explorer=World.Unit(explorerId);var site=s.Sites.First(x=>!x.Done);Prep(explorer,Location.Exterior,site.Position);Exploration.Send(explorer,site.Id);Orders.Tick(10);explorationIds=s.Orders[explorerId].Cargo.ToArray();Check(explorationIds.Length==3,"active exploration return cargo before save");
  var guard=World.Unit(guardId);Defense.AssignPatrol(guard);Orders.Tick(.1f);
  Store(engineer,rooms["FreightWarehouse"],"SupplyCrate",4);s.TradeCooldown=0;Check(Commerce.Accept(0).Contains("aceptado")&&Commerce.Export().Contains("entregada"),"second contract saved during loaded shipment");Commerce.Tick(15);contractAtSave=s.Contract;coinsAtSave=Resource.getCountOfType(ResourceTypeList.CoinsInstance);resourcesAtSave=Resource.getCount();trainingAtSave=s.Orders[traineeId].Work;
  Check(s.Orders.Count>=5,"freight, exploration, rescue, training and patrol active together");
  Selection.clear();save=SaveData.getSavePath();AccessTools.Field(typeof(GameStateGame),"mSavePath").SetValue(game,save);self.Logger.LogInfo("COMMUNITY QA saving active tasks to "+save);
 }
 static void Reload()
 {
  var s=CommunityState.Current;rooms.Clear();foreach(var m in World.Modules.Where(m=>m.getModuleType() is ICommunityModule))rooms[m.getModuleType().GetType().Name.Replace("ModuleType","")]=m;foreach(var m in World.Modules)Supply(m);
  var restored=Singleton<TerrainGenerator>.getInstance();restored.flatten(new Vector3(1260,0,1140),170,restored.getFloorHeight());restored.clearArea(new Vector3(1260,0,1140),170);Physics.SyncTransforms();RegenerateExterior();foreach(var o in s.Orders.Values)if(World.Unit(o.Unit)?.getLocation()==Location.Exterior)World.Unit(o.Unit).setIdle();
  Check(rooms.Count==16,"all sixteen new building types persist after reload");Check(Resource.getCount()==resourcesAtSave,"physical resource count unchanged by save/load");Check(Resource.getCountOfType(ResourceTypeList.CoinsInstance)==coinsAtSave,"currency unchanged by save/load");Check(s.Orders.ContainsKey(haulerId)&&s.Orders[haulerId].Cargo.SequenceEqual(freightIds),"three freight resource identities persist");Check(freightIds.All(id=>World.Cargo(id)?.getState()==Resource.State.Loaded),"loaded freight resources survive reload");Check(s.Orders[explorerId].Cargo.SequenceEqual(explorationIds),"expedition cargo identities persist");Check(s.Sites.Count(x=>x.Done)==2,"exhausted exploration sites remain exhausted");Check(s.Orders[traineeId].Work==trainingAtSave,"training progress persists exactly");Check(Orders.Passenger(World.Unit(patientId))?.Unit==rescuerId,"patient and ambulance assignment survive reload");Check(s.Contract==contractAtSave&&s.ExportLoaded&&s.Shipping==30,"commercial escrow survives mid-shipment reload");
  Commerce.Tick(30);Check(s.Contract==-1&&Resource.getCountOfType(ResourceTypeList.CoinsInstance)==coinsAtSave+250,"resumed shipment pays exactly once");Commerce.Tick(30);Check(Resource.getCountOfType(ResourceTypeList.CoinsInstance)==coinsAtSave+250,"resumed shipment cannot pay twice");
  var trainee=World.Unit(traineeId);string profession=s.Orders[traineeId].Kind;var desk=World.Modules.SelectMany(m=>m.getComponents()).Single(c=>c.getComponentType() is TrainingConsole);Prep(trainee,Location.Interior,desk.getAnchorPoint().position,false);Orders.Tick(.1f);Orders.Tick(300-trainingAtSave);Orders.Tick(.1f);Check(trainee.getSpecialization().GetType().Name==profession,"training changes native profession after resumed study");Check(Character.getSpecializationCharacters(trainee.getSpecialization()).Contains(trainee),"profession index updated consistently");
  var hauler=World.Unit(haulerId);int cargoCount=Resource.getCount();Orders.Cancel(haulerId);Check(freightIds.All(id=>World.Cargo(id)!=null&&World.Cargo(id).getState()!=Resource.State.Loaded),"cancelling loaded route drops all three crates");Check(Resource.getCount()==cargoCount,"cancelling route never creates or destroys cargo");
  var rescuer=World.Unit(rescuerId);var patient=World.Unit(patientId);for(int i=0;i<3500&&s.Orders.ContainsKey(rescuerId);i++){NavigationGraph.update();rescuer.update(.1f);Interaction.updateAll(.1f);Orders.Tick(.1f);}Check(!s.Orders.ContainsKey(rescuerId)&&patient.getLocation()==Location.Interior,"ambulance transports patient through airlock to hospital");Check(patient.anyInteractions()&&patient.getFirstInteraction().getSelectable() is ConstructionComponent bed&&bed.getComponentType() is TraumaBed,"patient enters native hospital bed interaction");
  var medic=World.Characters.First(c=>c is Colonist&&c.getSpecialization() is Medic);Prep(medic,Location.Interior,patient.getPosition()+Vector3.right);var medicine=Resource.create(ResourceTypeList.MedicalSuppliesInstance,medic.getPosition(),Location.Interior);medic.loadResource(medicine);float oldHealth=Value(patient,CharacterIndicator.Health);var treatment=Interaction.create<InteractionRestore>(medic,patient);Check(treatment.update(60),"native medical treatment completes");Check(Value(patient,CharacterIndicator.Health)>oldHealth&&medicine.isDestroyed(),"native hospital care heals patient and consumes medicine");treatment.destroy();
  var patrol=World.Unit(guardId);Orders.Cancel(guardId);Orders.Cancel(explorerId);
  var airlock=Module.findOfType(TypeList<ModuleType,ModuleTypeList>.find<ModuleTypeAirlock>());var evacuee=World.Characters.First(c=>c is Colonist&&c!=patient&&c!=medic&&c.getId()!=traineeId&&!(c.getSpecialization() is Guard));Prep(evacuee,Location.Exterior,airlock.getPoint("exit_point").position+Vector3.right*5);Orders.Emergency();Orders.Tick(1);Check(s.Orders.TryGetValue(evacuee.getId(),out var evacuation)&&evacuation.Mode=="evacuate","emergency assigns exterior civilian an evacuation route");
  for(int i=0;i<4500&&s.Orders.ContainsKey(evacuee.getId());i++){NavigationGraph.update();evacuee.update(.1f);Interaction.updateAll(.1f);Orders.Tick(.1f);}Check(evacuee.getLocation()==Location.Interior&&!s.Orders.ContainsKey(evacuee.getId()),"civilian evacuates through airlock and corridors to shelter");Orders.Emergency();Check(Singleton<SecurityManager>.getInstance().getAlertState()==AlertState.NoAlert,"ending community emergency restores previous no-alert state");Singleton<SecurityManager>.getInstance().setAlertState(AlertState.RedAlert);Orders.Emergency();Orders.Emergency();Check(Singleton<SecurityManager>.getInstance().getAlertState()==AlertState.RedAlert,"community emergency preserves a pre-existing native red alert");Singleton<SecurityManager>.getInstance().setAlertState(AlertState.NoAlert);
  SiteScene.Sync();var terrain=Singleton<TerrainGenerator>.getInstance();terrain.flatten(new Vector3(1260,0,1140),170,terrain.getFloorHeight());terrain.clearArea(new Vector3(1260,0,1140),170);Physics.SyncTransforms();
  foreach(var m in rooms.Values){Check(m.isBuilt(),"new building built after reload "+m.getName());Check(m.getGameObject().GetComponentsInChildren<Transform>(true).Any(t=>t.name=="Room roof architecture"||t.name=="Community exterior architecture"),"own geometry survives reload "+m.getName());}
  self.Logger.LogInfo("COMMUNITY QA MECHANICS PASSED: "+checks+" checks; save/load, six systems and physical routes.");
 }
 static Module Make(string id,Vector3 p){var t=TypeList<ModuleType,ModuleTypeList>.get().Single(x=>x.GetType().Name=="ModuleType"+id);Check(!t.getName().Contains(id),"localized building "+id);var m=Module.create(p,t.getMinSize(),t);Physics.SyncTransforms();Check(m.canPlaceModule(p,Vector3.up,Module.ValidSizes[t.getMinSize()]),"native placement "+id);Finish(m);return m;}
 static void Link(Module a,Module b){Check(Connection.canLink(a,b),"native link "+b.getName());Finish(Connection.create(a,b));}
 static void Finish(Buildable b){b.onUserPlaced();var cost=b.calculateCost();foreach(var t in TypeList<ResourceType,ResourceTypeList>.get())for(int i=0;i<cost.getAmount(t);i++)b.addConstructionMaterial(Resource.create(t,b.getPosition(),b.getBuildLocation()));b.startBuilding();Check(b.updateBuild(1000)&&b.isBuilt(),"native construction "+b.getName());}
 static void Equip<T>(string room){var m=rooms[room];var c=ConstructionComponent.create(m,TypeList<ComponentType,ComponentTypeList>.find<T>());bool ok=false;for(int x=-8;x<=8&&!ok;x++)for(int z=-8;z<=8&&!ok;z++){c.setPosition(m.getFloorPosition()+new Vector3(x*.5f,0,z*.5f));c.setRotation(Quaternion.identity);ok=m.canPlaceComponent(c);}Check(ok,"native furnishing placement "+typeof(T).Name);m.getComponents().Add(c);Finish(c);equipment[typeof(T).Name]=c;Supply(m);}
 static void Supply(Module m){m.setPower(true);m.setHasWater(true);m.getOxygenIndicator().setValue(1);}
 static void Prep(Character c,Location location,Vector3 p,bool clearOrder=true){if(clearOrder)Orders.Cancel(c.getId());AccessTools.Method(typeof(Character),"destroyInteractions").Invoke(c,null);if(c.isLoaded())c.unloadResource(Resource.State.Idle);c.setIdle();World.Location(c,location);c.setPosition(p);foreach(var indicator in c.getIndicators())if(indicator!=null)indicator.setValue(1);}
 static void Set(Character c,CharacterIndicator which,float value){((Indicator[])AccessTools.Field(typeof(Character),"mIndicators").GetValue(c))[(int)which].setValue(value);}
 static float Value(Character c,CharacterIndicator which)=>((Indicator[])AccessTools.Field(typeof(Character),"mIndicators").GetValue(c))[(int)which].getValue();
 static void StockMachine(ConstructionComponent c,params string[] types){foreach(string kind in types)Check(c.getResourceContainer().add(Resource.create(TypeList<ResourceType,ResourceTypeList>.find(kind),c.getPosition(),Location.Interior)),"recipe input accepted "+kind);}
 static void Produce(Character c,ConstructionComponent machine){Prep(c,Location.Interior,machine.getAnchorPoint().position);var interaction=Interaction.create<InteractionWork>(c,machine);AccessTools.Method(typeof(ConstructionComponent),"updateProduction").Invoke(machine,new object[]{1000f});interaction.destroy();}
 static void Store(Character c,Module m,string kind,int amount){Prep(c,Location.Interior,m.getFloorPosition());for(int i=0;i<amount;i++){var r=Resource.create(TypeList<ResourceType,ResourceTypeList>.find(kind),c.getPosition(),Location.Interior);c.loadResource(r);c.storeResource(m);Check(r.getState()==Resource.State.Stored,"fixture stored resource "+kind);}}
 static int Stored(Module m,string kind)=>World.Resources.Count(r=>r.getState()==Resource.State.Stored&&r.getResourceType().GetType().Name==kind&&(r.getPosition()-m.getPosition()).sqrMagnitude<m.getRadius()*m.getRadius());
 static void GiveCoins(int count){int n=Resource.getCountOfType(ResourceTypeList.CoinsInstance);if(n<count)Resource.addInmaterialResource(new ResourceAmount(ResourceTypeList.CoinsInstance,count-n));}
 static void RegenerateExterior(){var nav=NavigationGraph.getExterior();nav.createGrid(Singleton<TerrainGenerator>.getInstance().getCenter());Singleton<TerrainGenerator>.getInstance().updateNavigation();foreach(var m in World.Modules.Where(m=>m.isBuilt()))nav.addBlocker(m.getPosition(),(float)AccessTools.Method(typeof(Module),"getNavRadius").Invoke(m,null));var all=(List<Construction>)AccessTools.Field(typeof(Construction),"mConstructions").GetValue(null);foreach(var c in all.OfType<Connection>().Where(c=>c.isBuilt()&&c.getLocation()==Location.Interior))AccessTools.Method(typeof(Connection),"setExteriorGraphBlocked").Invoke(c,new object[]{true});NavigationGraph.requestUpdateCache();NavigationGraph.update();}
 [HarmonyPatch(typeof(GameStateGame),nameof(GameStateGame.isEndOfFramePending))]
 static class Frames{static void Postfix(ref bool __result){if(step>=2&&step<=6)__result=true;}}
 [HarmonyPatch(typeof(GameStateGame),nameof(GameStateGame.onGui))]
 static class Clean{static bool Prefix(){return step!=5||Photos[shot].StartsWith("interface-");}}
 [HarmonyPatch(typeof(GameStateGame),nameof(GameStateGame.onEndOfFrame))]
 static class End
 {
  static void Postfix(GameStateGame __instance){try{
   if(step==2&&File.Exists(save)){var xml=new XmlDocument();xml.Load(save);Check(xml.SelectSingleNode("//community-expansion")!=null,"colony expansion state serialized");step=3;GameManager.getInstance().setGameStateGameLoad(save,0,null);}
   else if(step==4&&Time.realtimeSinceStartup>captureAt){step=5;Pose();}
   else if(step==5&&Time.realtimeSinceStartup>captureAt){Directory.CreateDirectory(Path.Combine(output,"capturas"));File.WriteAllBytes(Path.Combine(output,"capturas",Photos[shot]+".jpg"),Util.captureScreenshot(1000));self.Logger.LogInfo("COMMUNITY CAPTURE "+Photos[shot]);shot++;if(shot<Photos.Length)Pose();else{step=6;Studio.Begin(output,()=>{step=7;self.Logger.LogInfo("COMMUNITY QA PASSED: "+checks+" checks; "+shot+" colony screenshots; 37 model renders; isolated profile.");});}}
  }catch(Exception e){Fail(e);}}
 }
 static void Pose(){var game=(GameStateGame)GameManager.getInstance().getGameState();var gui=(GameGui)AccessTools.Field(typeof(GameStateGame),"mGameGui").GetValue(game);string name=Photos[shot];if(name.StartsWith("interface-")){gui.setWindow(new CommunityWindow(gui,int.Parse(name.Split('-')[1])));captureAt=Time.realtimeSinceStartup+1;return;}gui.setWindow(null);bool inside=name.EndsWith("-inside");var m=rooms[name.Replace("-inside","")];var target=m.getPosition()+Vector3.up*(inside?.4f:2.0f);var rotation=Quaternion.Euler(inside?55:32,inside?215:35,0);var camera=CameraManager.getInstance();camera.focusOnPosition(target,10);camera.setCameraTransform(new SimpleTransform(target-rotation*Vector3.forward*(inside?15:16),rotation));AccessTools.Field(typeof(GameStateGame),"mRenderTops").SetValue(game,!inside);Construction.setRenderTops(!inside,true);Selection.clear();captureAt=Time.realtimeSinceStartup+1.3f;}
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;self.Logger.LogInfo("COMMUNITY PASS "+checks+": "+label);}
 static void Fail(Exception e){if(step<0)return;step=-1;self.Logger.LogError("COMMUNITY QA FAILED: "+e);}
}
